import type { EmailVariableDefinition } from "./email-template-registry";

/** Broadcasts go to one group only: people who turned on content notifications (and are not blocked). */
export type CreateBroadcastInput = {
  subjectPl: string;
  htmlPl: string;
  subjectEn?: string | null;
  htmlEn?: string | null;
  /** Generated by the wizard when it opens; repeating the request returns the same broadcast. */
  requestKey: string;
};

export type CreateBroadcastResult = {
  broadcastId: string;
  recipientCount: number;
  /** True when this request key already created the broadcast earlier. */
  duplicate: boolean;
};

export type SendBroadcastTestInput = {
  subjectPl: string;
  htmlPl: string;
  subjectEn?: string | null;
  htmlEn?: string | null;
  language: "pl" | "en";
  /** Admin panel: the signed-in panel account's own address (never taken from a form). */
  recipient?: { email: string; name: string };
};

export type BroadcastCounts = {
  pending: number;
  sent: number;
  failed: number;
  skipped: number;
};

export type AdminBroadcastEmailListItemDto = {
  id: string;
  subjectPl: string;
  subjectEn: string;
  htmlPl: string;
  htmlEn: string;
  status: string;
  recipientCount: number;
  counts: BroadcastCounts;
  sentAt: Date | null;
  createdAt: Date;
  createdById: string | null;
};

export type EmailTemplateDto = {
  id: string;
  slug: string;
  name: string | null;
  description: string | null;
  /** A mail the application sends by itself (its default text lives in code). */
  isSystem: boolean;
  /** An admin saved this text; for a system mail it replaces the default ("Przywróć domyślny" removes it). */
  isCustomized: boolean;
  subject: string;
  html: string;
  subjectEn: string | null;
  htmlEn: string | null;
  updatedAt: Date | null;
  /** Variables this template may use; the same list the sender fills. */
  variables: EmailVariableDefinition[];
};

export type UpsertEmailTemplateInput = {
  slug: string;
  name?: string | null;
  description?: string | null;
  subject: string;
  html: string;
  subjectEn?: string | null;
  htmlEn?: string | null;
};
